variants.1x1-f32-shared:
// Adapted from https://huggingface.co/kernels/webgpu-kernels/ai.onnx.Conv/resolve/7b19a1ea4fd2abef3203991ca933405f12cfcc62/build/webgpu/conv-1x1-subgroup-matrix.wgsl.jinja
// Apache-2.0; see LICENSE. Integration MIT, https://github.com/barhanc/wgpu-executorch
// Batched subgroup-matrix product C[b] (M x N) = A (M x K) * B[b] (K x N).
// A is row-major; B may be a direct matrix view, a materialized column matrix,
// or an on-demand gather. Accumulation is f32. A configured epilogue may apply
// bias or other output transforms after the full K reduction.
//
// Full 8x8 matrix loads require complete K/N tiles. The aligned path enforces
// that geometry; `padded` zero-fills tails, and `implicitIm2col` gathers and
// zero-fills directly from NCHW without materializing the column matrix.
//
// `splitK` assigns disjoint K ranges to workgroup_id.z. Each slice writes raw
// sums to tile-padded [splitK,batch,M_PAD,N_PAD] scratch; a later pass combines
// the slices and applies bias or an epilogue. Padded tail cells remain zero and
// are never copied to the logical output.

































enable subgroups;

enable subgroup_size_control;

enable chromium_experimental_subgroup_matrix;
diagnostic(off, chromium.subgroup_matrix_uniformity);


    @group(0) @binding(0) var<storage, read_write> y: array<f32>;
    @group(0) @binding(1) var<storage, read> xm: array<f32>;
    @group(0) @binding(2) var<storage, read> w: array<f32>;
    @group(0) @binding(3) var<storage, read> bias: array<f32>;
    struct Params { has_bias: u32 }
    @group(0) @binding(4) var<uniform> params: Params;













override M: u32 = 1u;
override K: u32 = 32u;

override N: u32 = 64u;




override B_BATCH_STRIDE: u32 = K * N;


override C_BATCH_STRIDE: u32 = M * N;


const TILE_COLS: u32 = 64u;
const TILE_ROWS: u32 = 32u;
const TILE_K: u32 = 32u;
const SUB_COLS: u32 = 32u;
const SUB_ROWS: u32 = 16u;


var<workgroup> tile_A: array<f32, 32 * 32>;
var<workgroup> tile_B: array<f32, 64 * 32>;


var<workgroup> scratch: array<array<array<f32, 64>, 4>, 4>;



fn loadSHMA(tile_base: u32, k_idx: u32, row: u32, c_idx: u32) {
  let a_global = tile_base + row;
  let col = c_idx * 8u;
  for (var col_offset = 0u; col_offset < 8u; col_offset = col_offset + 1u) {
    let k = k_idx + col + col_offset;
    if (a_global < M) {


      tile_A[row * TILE_K + col + col_offset] = f32(w[a_global * K + k]);

    } else {

      tile_A[row * TILE_K + col + col_offset] = 0.0;

    }
  }
}

fn loadSHMB(b_base: u32, tile_base: u32, k_idx: u32, row: u32, c_idx: u32) {
  let b_col = tile_base + row;
  let col = c_idx * 16u;

  for (var i = 0u; i < 16u; i = i + 1u) {
    let k = k_idx + col + i;

    tile_B[row * TILE_K + col + i] = f32(xm[b_base + k * N + b_col]);

  }

}






fn storeOutput(offset: u32, row_base: u32, row: u32, col: u32, src_slot: u32, row_limit: i32) {
  if (row_limit > 0 && row < u32(row_limit)) {
    let col2 = col + 1u;

    var bv = 0.0; if (params.has_bias != 0u) { bv = f32(bias[row_base + row]); }


    y[offset + row * N + col]       = 

f32(scratch[src_slot][0][row * 8u + col] + bv);
    y[offset + row * N + col + 8u]  = 

f32(scratch[src_slot][1][row * 8u + col] + bv);
    y[offset + row * N + col + 16u] = 

f32(scratch[src_slot][2][row * 8u + col] + bv);
    y[offset + row * N + col + 24u] = 

f32(scratch[src_slot][3][row * 8u + col] + bv);

    y[offset + row * N + col2]       = 

f32(scratch[src_slot][0][row * 8u + col2] + bv);
    y[offset + row * N + col2 + 8u]  = 

f32(scratch[src_slot][1][row * 8u + col2] + bv);
    y[offset + row * N + col2 + 16u] = 

f32(scratch[src_slot][2][row * 8u + col2] + bv);
    y[offset + row * N + col2 + 24u] = 

f32(scratch[src_slot][3][row * 8u + col2] + bv);

  }
}


@compute @workgroup_size(128, 1, 1) @subgroup_size(32)
fn main(
  @builtin(workgroup_id) workgroup_id: vec3<u32>,
  @builtin(local_invocation_index) local_idx: u32,

  @builtin(subgroup_invocation_id) sg_id: u32,

  @builtin(subgroup_size) sg_size: u32
) {

  let batch = workgroup_id.z;
  let b_base = batch * B_BATCH_STRIDE;
  let c_base = batch * C_BATCH_STRIDE;

  let a_global_base = workgroup_id.y * TILE_ROWS;
  let b_global_base = workgroup_id.x * TILE_COLS;
  let subtile_id = local_idx / sg_size;
  let subtile_idx = subtile_id / 2u;
  let subtile_idy = subtile_id % 2u;
  let base_A = subtile_idy * SUB_ROWS;
  let base_B = subtile_idx * SUB_COLS;

  var matC00: subgroup_matrix_result<f32, 8, 8>;
  var matC01: subgroup_matrix_result<f32, 8, 8>;
  var matC02: subgroup_matrix_result<f32, 8, 8>;
  var matC03: subgroup_matrix_result<f32, 8, 8>;
  var matC10: subgroup_matrix_result<f32, 8, 8>;
  var matC11: subgroup_matrix_result<f32, 8, 8>;
  var matC12: subgroup_matrix_result<f32, 8, 8>;
  var matC13: subgroup_matrix_result<f32, 8, 8>;


  for (var kidx = 0u; kidx < K; kidx = kidx + TILE_K) {


    loadSHMA(a_global_base, kidx, local_idx / 4u, local_idx % 4u);
    loadSHMB(b_base, b_global_base, kidx, local_idx / 2u, local_idx % 2u);
    workgroupBarrier();


    for (var step = 0u; step < TILE_K; step = step + 8u) {

      let matrix_a_offset = subtile_idy * SUB_ROWS * TILE_K + step;

      var matA0: subgroup_matrix_left<f32, 8, 8> = subgroupMatrixLoad<subgroup_matrix_left<f32, 8, 8>, row_major>(&tile_A, matrix_a_offset, TILE_K);

      var matA1: subgroup_matrix_left<f32, 8, 8> = subgroupMatrixLoad<subgroup_matrix_left<f32, 8, 8>, row_major>(&tile_A, matrix_a_offset + 8u * TILE_K, TILE_K);


      let matrix_b_offset = subtile_idx * SUB_COLS * TILE_K + step;

      var matB0: subgroup_matrix_right<f32, 8, 8> = subgroupMatrixLoad<subgroup_matrix_right<f32, 8, 8>, col_major>(&tile_B, matrix_b_offset, TILE_K);

      var matB1: subgroup_matrix_right<f32, 8, 8> = subgroupMatrixLoad<subgroup_matrix_right<f32, 8, 8>, col_major>(&tile_B, matrix_b_offset + 8u * TILE_K, TILE_K);

      var matB2: subgroup_matrix_right<f32, 8, 8> = subgroupMatrixLoad<subgroup_matrix_right<f32, 8, 8>, col_major>(&tile_B, matrix_b_offset + 16u * TILE_K, TILE_K);

      var matB3: subgroup_matrix_right<f32, 8, 8> = subgroupMatrixLoad<subgroup_matrix_right<f32, 8, 8>, col_major>(&tile_B, matrix_b_offset + 24u * TILE_K, TILE_K);


      matC00 = subgroupMatrixMultiplyAccumulate(matA0, matB0, matC00);
      matC01 = subgroupMatrixMultiplyAccumulate(matA0, matB1, matC01);
      matC02 = subgroupMatrixMultiplyAccumulate(matA0, matB2, matC02);
      matC03 = subgroupMatrixMultiplyAccumulate(matA0, matB3, matC03);
      matC10 = subgroupMatrixMultiplyAccumulate(matA1, matB0, matC10);
      matC11 = subgroupMatrixMultiplyAccumulate(matA1, matB1, matC11);
      matC12 = subgroupMatrixMultiplyAccumulate(matA1, matB2, matC12);
      matC13 = subgroupMatrixMultiplyAccumulate(matA1, matB3, matC13);
    }

    workgroupBarrier();

  }



  // The four scratch banks are reused across the two row-groups, and each is written
  // by a collective subgroupMatrixStore then read CROSS-LANE by storeOutput. Barriers
  // give the reads visibility of the store AND stop the second row-group's store from
  // clobbering the first's still-in-flight readback when a partial final M-tile
  // diverges storeOutput's guard. Without both barriers the last valid row can be corrupted.
  subgroupMatrixStore<row_major>(&scratch[subtile_id][0], 0u, matC00, 8u);
  subgroupMatrixStore<row_major>(&scratch[subtile_id][1], 0u, matC01, 8u);
  subgroupMatrixStore<row_major>(&scratch[subtile_id][2], 0u, matC02, 8u);
  subgroupMatrixStore<row_major>(&scratch[subtile_id][3], 0u, matC03, 8u);
  workgroupBarrier();
  let row = sg_id / 4u;
  let col = (sg_id % 4u) * 2u;
  let row_base = a_global_base + base_A;
  var matrix_c_offset = c_base + row_base * N + b_global_base + base_B;
  var row_limit = i32(M) - i32(row_base);
  storeOutput(matrix_c_offset, row_base, row, col, subtile_id, row_limit);
  workgroupBarrier();

  subgroupMatrixStore<row_major>(&scratch[subtile_id][0], 0u, matC10, 8u);
  subgroupMatrixStore<row_major>(&scratch[subtile_id][1], 0u, matC11, 8u);
  subgroupMatrixStore<row_major>(&scratch[subtile_id][2], 0u, matC12, 8u);
  subgroupMatrixStore<row_major>(&scratch[subtile_id][3], 0u, matC13, 8u);
  workgroupBarrier();
  matrix_c_offset = matrix_c_offset + 8u * N;
  row_limit = i32(M) - i32(row_base + 8u);
  storeOutput(matrix_c_offset, row_base + 8u, row, col, subtile_id, row_limit);

}

variants.1x1-f32-direct:
// Adapted from https://huggingface.co/kernels/webgpu-kernels/ai.onnx.Conv/resolve/7b19a1ea4fd2abef3203991ca933405f12cfcc62/build/webgpu/conv-1x1-subgroup-matrix.wgsl.jinja
// Apache-2.0; see LICENSE. Integration MIT, https://github.com/barhanc/wgpu-executorch
// Batched subgroup-matrix product C[b] (M x N) = A (M x K) * B[b] (K x N).
// A is row-major; B may be a direct matrix view, a materialized column matrix,
// or an on-demand gather. Accumulation is f32. A configured epilogue may apply
// bias or other output transforms after the full K reduction.
//
// Full 8x8 matrix loads require complete K/N tiles. The aligned path enforces
// that geometry; `padded` zero-fills tails, and `implicitIm2col` gathers and
// zero-fills directly from NCHW without materializing the column matrix.
//
// `splitK` assigns disjoint K ranges to workgroup_id.z. Each slice writes raw
// sums to tile-padded [splitK,batch,M_PAD,N_PAD] scratch; a later pass combines
// the slices and applies bias or an epilogue. Padded tail cells remain zero and
// are never copied to the logical output.

































enable subgroups;

enable subgroup_size_control;

enable chromium_experimental_subgroup_matrix;
diagnostic(off, chromium.subgroup_matrix_uniformity);


    @group(0) @binding(0) var<storage, read_write> y: array<f32>;
    @group(0) @binding(1) var<storage, read> xm: array<f32>;
    @group(0) @binding(2) var<storage, read> w: array<f32>;
    @group(0) @binding(3) var<storage, read> bias: array<f32>;
    struct Params { has_bias: u32 }
    @group(0) @binding(4) var<uniform> params: Params;













override M: u32 = 1u;
override K: u32 = 32u;

override N: u32 = 64u;




override B_BATCH_STRIDE: u32 = K * N;


override C_BATCH_STRIDE: u32 = M * N;


const TILE_COLS: u32 = 64u;
const TILE_ROWS: u32 = 64u;
const TILE_K: u32 = 32u;
const SUB_COLS: u32 = 32u;
const SUB_ROWS: u32 = 16u;









@compute @workgroup_size(256, 1, 1) @subgroup_size(32)
fn main(
  @builtin(workgroup_id) workgroup_id: vec3<u32>,
  @builtin(local_invocation_index) local_idx: u32,

  @builtin(subgroup_size) sg_size: u32
) {

  let batch = workgroup_id.z;
  let b_base = batch * B_BATCH_STRIDE;
  let c_base = batch * C_BATCH_STRIDE;

  let a_global_base = workgroup_id.y * TILE_ROWS;
  let b_global_base = workgroup_id.x * TILE_COLS;
  let subtile_id = local_idx / sg_size;
  let subtile_idx = subtile_id / 4u;
  let subtile_idy = subtile_id % 4u;
  let base_A = subtile_idy * SUB_ROWS;
  let base_B = subtile_idx * SUB_COLS;

  var matC00: subgroup_matrix_result<f32, 8, 8>;
  var matC01: subgroup_matrix_result<f32, 8, 8>;
  var matC02: subgroup_matrix_result<f32, 8, 8>;
  var matC03: subgroup_matrix_result<f32, 8, 8>;
  var matC10: subgroup_matrix_result<f32, 8, 8>;
  var matC11: subgroup_matrix_result<f32, 8, 8>;
  var matC12: subgroup_matrix_result<f32, 8, 8>;
  var matC13: subgroup_matrix_result<f32, 8, 8>;


  for (var kidx = 0u; kidx < K; kidx = kidx + TILE_K) {



    for (var step = 0u; step < TILE_K; step = step + 8u) {

      let matrix_a_offset = (a_global_base + subtile_idy * SUB_ROWS) * K + kidx + step;

      var matA0: subgroup_matrix_left<f32, 8, 8> = subgroupMatrixLoad<subgroup_matrix_left<f32, 8, 8>, row_major>(&w, matrix_a_offset, K);

      var matA1: subgroup_matrix_left<f32, 8, 8> = subgroupMatrixLoad<subgroup_matrix_left<f32, 8, 8>, row_major>(&w, matrix_a_offset + 8u * K, K);


      let matrix_b_offset = b_base + (kidx + step) * N + b_global_base + subtile_idx * SUB_COLS;

      var matB0: subgroup_matrix_right<f32, 8, 8> = subgroupMatrixLoad<subgroup_matrix_right<f32, 8, 8>, row_major>(&xm, matrix_b_offset, N);

      var matB1: subgroup_matrix_right<f32, 8, 8> = subgroupMatrixLoad<subgroup_matrix_right<f32, 8, 8>, row_major>(&xm, matrix_b_offset + 8u, N);

      var matB2: subgroup_matrix_right<f32, 8, 8> = subgroupMatrixLoad<subgroup_matrix_right<f32, 8, 8>, row_major>(&xm, matrix_b_offset + 16u, N);

      var matB3: subgroup_matrix_right<f32, 8, 8> = subgroupMatrixLoad<subgroup_matrix_right<f32, 8, 8>, row_major>(&xm, matrix_b_offset + 24u, N);


      matC00 = subgroupMatrixMultiplyAccumulate(matA0, matB0, matC00);
      matC01 = subgroupMatrixMultiplyAccumulate(matA0, matB1, matC01);
      matC02 = subgroupMatrixMultiplyAccumulate(matA0, matB2, matC02);
      matC03 = subgroupMatrixMultiplyAccumulate(matA0, matB3, matC03);
      matC10 = subgroupMatrixMultiplyAccumulate(matA1, matB0, matC10);
      matC11 = subgroupMatrixMultiplyAccumulate(matA1, matB1, matC11);
      matC12 = subgroupMatrixMultiplyAccumulate(matA1, matB2, matC12);
      matC13 = subgroupMatrixMultiplyAccumulate(matA1, matB3, matC13);
    }

  }



  // Full f32 output tiles can be published by the subgroup-matrix collectives
  // directly. With no epilogue this removes scratch traffic and three barriers.
  // When an epilogue is present, publish the raw accumulators first, then apply
  // bias, residual Z, and activation cooperatively after one storage barrier.
  let matrix_c_offset = c_base + (a_global_base + base_A) * N + b_global_base + base_B;
  subgroupMatrixStore<row_major>(&y, matrix_c_offset + 0u * N +  0u, matC00, N);
  subgroupMatrixStore<row_major>(&y, matrix_c_offset + 0u * N +  8u, matC01, N);
  subgroupMatrixStore<row_major>(&y, matrix_c_offset + 0u * N + 16u, matC02, N);
  subgroupMatrixStore<row_major>(&y, matrix_c_offset + 0u * N + 24u, matC03, N);
  subgroupMatrixStore<row_major>(&y, matrix_c_offset + 8u * N +  0u, matC10, N);
  subgroupMatrixStore<row_major>(&y, matrix_c_offset + 8u * N +  8u, matC11, N);
  subgroupMatrixStore<row_major>(&y, matrix_c_offset + 8u * N + 16u, matC12, N);
  subgroupMatrixStore<row_major>(&y, matrix_c_offset + 8u * N + 24u, matC13, N);

  storageBarrier();
  for (var tile_idx = local_idx; tile_idx < TILE_ROWS * TILE_COLS; tile_idx += 256u) {
    let local_row = tile_idx / TILE_COLS;
    let local_col = tile_idx % TILE_COLS;
    let global_row = a_global_base + local_row;
    let global_col = b_global_base + local_col;
    let y_index = c_base + global_row * N + global_col;
    var raw = f32(y[y_index]);

    if (params.has_bias != 0u) { raw += f32(bias[global_row]); }

    y[y_index] = f32(raw);
  }




}

variants.3x3-f32-shared:
// Adapted from https://huggingface.co/kernels/webgpu-kernels/ai.onnx.Conv/resolve/7b19a1ea4fd2abef3203991ca933405f12cfcc62/build/webgpu/conv-1x1-subgroup-matrix.wgsl.jinja
// Apache-2.0; see LICENSE. Integration MIT, https://github.com/barhanc/wgpu-executorch
// Batched subgroup-matrix product C[b] (M x N) = A (M x K) * B[b] (K x N).
// A is row-major; B may be a direct matrix view, a materialized column matrix,
// or an on-demand gather. Accumulation is f32. A configured epilogue may apply
// bias or other output transforms after the full K reduction.
//
// Full 8x8 matrix loads require complete K/N tiles. The aligned path enforces
// that geometry; `padded` zero-fills tails, and `implicitIm2col` gathers and
// zero-fills directly from NCHW without materializing the column matrix.
//
// `splitK` assigns disjoint K ranges to workgroup_id.z. Each slice writes raw
// sums to tile-padded [splitK,batch,M_PAD,N_PAD] scratch; a later pass combines
// the slices and applies bias or an epilogue. Padded tail cells remain zero and
// are never copied to the logical output.

































enable subgroups;

enable subgroup_size_control;

enable chromium_experimental_subgroup_matrix;
diagnostic(off, chromium.subgroup_matrix_uniformity);


    @group(0) @binding(0) var<storage, read_write> y: array<f32>;
    @group(0) @binding(1) var<storage, read> xm: array<f32>;
    @group(0) @binding(2) var<storage, read> w: array<f32>;
    @group(0) @binding(3) var<storage, read> bias: array<f32>;
    struct Params { has_bias: u32 }
    @group(0) @binding(4) var<uniform> params: Params;













override CONV_IN_CHANNELS: u32 = 1u;
override M: u32 = 1u;
override K: u32 = 32u;

override N: u32 = 64u;


override K_LOOP: u32 = 32u;


const CONV_KERNEL_H: u32 = 3u;
const CONV_KERNEL_W: u32 = 3u;

const CONV_KSIZE: u32 = CONV_KERNEL_H * CONV_KERNEL_W;

override CONV_STRIDE_H: u32 = 1u;
override CONV_STRIDE_W: u32 = 1u;
override CONV_DILATION_H: u32 = 1u;
override CONV_DILATION_W: u32 = 1u;
override CONV_PAD_TOP: i32 = 1;
override CONV_PAD_LEFT: i32 = 1;
override CONV_IN_H: i32 = 1;
override CONV_IN_W: i32 = 1;
override CONV_OUT_W: u32 = 1u;

// X is [batch, inChannels, inH, inW]; the tile gather indexes it directly.
override B_BATCH_STRIDE: u32 = CONV_IN_CHANNELS * u32(CONV_IN_H) * u32(CONV_IN_W);



override C_BATCH_STRIDE: u32 = M * N;


const TILE_COLS: u32 = 64u;
const TILE_ROWS: u32 = 32u;
const TILE_K: u32 = 32u;
const SUB_COLS: u32 = 32u;
const SUB_ROWS: u32 = 16u;


var<workgroup> tile_A: array<f32, 32 * 32>;
var<workgroup> tile_B: array<f32, 64 * 32>;


var<workgroup> scratch: array<array<array<f32, 64>, 4>, 4>;



fn loadSHMA(tile_base: u32, k_idx: u32, row: u32, c_idx: u32) {
  let a_global = tile_base + row;
  let col = c_idx * 8u;
  for (var col_offset = 0u; col_offset < 8u; col_offset = col_offset + 1u) {
    let k = k_idx + col + col_offset;
    if (a_global < M && k < K) {


      tile_A[row * TILE_K + col + col_offset] = f32(w[a_global * K + k]);

    } else {

      tile_A[row * TILE_K + col + col_offset] = 0.0;

    }
  }
}

fn loadSHMB(b_base: u32, tile_base: u32, k_idx: u32, row: u32, c_idx: u32) {
  let b_col = tile_base + row;
  let col = c_idx * 16u;

  // One output position per tile column, so its window origin is loop-invariant.

  let ih0 = i32((b_col / CONV_OUT_W) * CONV_STRIDE_H) - CONV_PAD_TOP;

  let iw0 = i32((b_col % CONV_OUT_W) * CONV_STRIDE_W) - CONV_PAD_LEFT;
  let in_column = b_col < N;
  // k advances by exactly one per element, so the (in-channel, tap-row, tap-col)
  // decomposition is CARRIED across the loop instead of recomputed: two divisions
  // and two moduli per loaded element become one increment and one compare, with
  // the source coordinates advanced by the dilation in step. Only the entry values
  // divide, and their divisors are compile-time literals.
  var k = k_idx + col;
  var ic = k / CONV_KSIZE;
  var kq = k % CONV_KSIZE;

  var kh = kq / CONV_KERNEL_W;
  var kw = kq % CONV_KERNEL_W;

  var ih = ih0 + i32(kh * CONV_DILATION_H);
  var iw = iw0 + i32(kw * CONV_DILATION_W);
  // A tile column whose whole kernel window and K span are in bounds cannot
  // take any of the element guards below. Hoist them into one uniform test so
  // the interior loop carries a plain address instead of recomputing coordinates.
  let interior = in_column
    && k_idx + col + 16u <= K

    && ih0 >= 0 && ih0 + i32((CONV_KERNEL_H - 1u) * CONV_DILATION_H) < CONV_IN_H
    && iw0 >= 0 && iw0 + i32((CONV_KERNEL_W - 1u) * CONV_DILATION_W) < CONV_IN_W;
  if (interior) {
    let colStep = i32(CONV_DILATION_W);
    let rowStep = i32(CONV_DILATION_H) * CONV_IN_W;

    let planeStep = CONV_IN_H * CONV_IN_W;

    // Advancing k already added one colStep, so each wrap rewinds that plus the taps it walked.
    let kwWrap = colStep * i32(CONV_KERNEL_W) - rowStep;

    let khWrap = rowStep * i32(CONV_KERNEL_H) - planeStep;
    var addr = i32(b_base) + i32(ic) * planeStep + ih * CONV_IN_W + iw;

    for (var i = 0u; i < 16u; i = i + 1u) {
      tile_B[row * TILE_K + col + i] = f32(xm[u32(addr)]);
      addr = addr + colStep;
      kw = kw + 1u;
      if (kw == CONV_KERNEL_W) {
        kw = 0u;
        addr = addr - kwWrap;
        kh = kh + 1u;
        if (kh == CONV_KERNEL_H) {
          kh = 0u;
          addr = addr - khWrap;

        }
      }
    }
    return;
  }
  for (var i = 0u; i < 16u; i = i + 1u) {
    var value = f32(0.0);
    // The K and N tails read as exact zeros, exactly as the materialized padded
    // cols buffer does, so they contribute nothing to the dot product.
