  let batch = workgroup_id.z;
  let b_base = batch * B_BATCH_STRIDE;
  let c_base = batch * C_BATCH_STRIDE;

  let a_global_base = workgroup_id.y * TILE_ROWS;
  let b_global_base = workgroup_id.x * TILE_COLS;
