      var matA0: subgroup_matrix_left<f32, 8, 8> = subgroupMatrixLoad<subgroup_matrix_left<f32, 8, 8>, row_major>(&tile_A, matrix_a_offset, TILE_K);

      var matA1: subgroup_matrix_left<f32, 8, 8> = subgroupMatrixLoad<subgroup_matrix_left<f32, 8, 8>, row_major>(&tile_A, matrix_a_offset + 8u * TILE_K, TILE_K);


      let matrix_b_offset = subtile_idx * SUB_COLS * TILE_K + step;

      var matB0: subgroup_matrix_right<f32, 8, 8> = subgroupMatrixLoad<subgroup_matrix_right<f32, 8, 8>, col_major>(&tile_B, matrix_b_offset, TILE_K);

      var matB1: subgroup_matrix_right<f32, 8, 8> = subgroupMatrixLoad<subgroup_matrix_right<f32, 8, 8>, col_major>(&tile_B, matrix_b_offset + 8u * TILE_K, TILE_K);

