  subgroupMatrixStore<row_major>(&scratch[subtile_id][2], 0u, matC02, 8u);
  subgroupMatrixStore<row_major>(&scratch[subtile_id][3], 0u, matC03, 8u);
  workgroupBarrier();
  let row = sg_id / 4u;
  let col = (sg_id % 4u) * 2u;
  let row_base = a_global_base + base_A;
  var matrix_c_offset = c_base + row_base * N + b_global_base + base_B;
  var row_limit = i32(M) - i32(row_base);
